   383	func buildCheckpointMetricDelta(baseline, current int) *checkpointTokensMetricDelta {
   384		delta := &checkpointTokensMetricDelta{
   385			Baseline:  baseline,
   386			Current:   current,
   387			Change:    current - baseline,
   388			Direction: checkpointDeltaDirection(current - baseline),
   389		}
   390		if baseline != 0 {
